import math

phase = 'PULL_FORWARD'
fwd_timer = 0.0

def control(obs):
    global phase, fwd_timer
    look_deg = 165.0
    hitch = obs.get('hitch_deg', 0.0)
    dt = obs.get('dt', 0.1)

    if phase == 'PULL_FORWARD':
        fwd_timer += dt
        steer = 15.0
        speed = 0.6
        if fwd_timer > 3.0 and abs(hitch) < 5.0:
            phase = 'REVERSE'
        return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look_deg}

    views = obs.get('views', {})
    left_clearance = 999.0
    right_clearance = 999.0
    for vname, vdata in views.items():
        origin = vdata.get('origin', [0, 0])
        for pt in vdata.get('walls', []):
            b_deg, d = pt[0], pt[1]
            rad = math.radians(b_deg)
            px = origin[0] + d * math.cos(rad)
            py = origin[1] + d * math.sin(rad)
            if -2.0 <= px <= 0.5:
                if py > 0 and py < left_clearance:
                    left_clearance = py
                elif py < 0 and abs(py) < right_clearance:
                    right_clearance = abs(py)

    target_hitch = -1.5
    if left_clearance < 900 and right_clearance < 900:
        margin = left_clearance - right_clearance
        if margin < 0.4:
            target_hitch = -3.0
        elif margin > 0.8:
            target_hitch = 1.0
        else:
            target_hitch = -1.0
    elif left_clearance < 0.8:
        target_hitch = -3.5

    rem = obs.get('progress', {}).get('remaining', 10.0)
    if rem < 1.2:
        target_hitch = 0.0

    error = hitch - target_hitch
    steer = 2.0 * error
    steer = max(-22.0, min(22.0, steer))
    speed = -0.35

    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look_deg}

