import math

def control(obs):
    look_target = -41.0
    speed = -1.2
    hitch = obs.get('hitch_deg', 0.0)
    views = obs.get('views', {})
    cam = views.get('camera')

    left_dist = 999.0
    right_dist = 999.0

    if cam and 'walls' in cam:
        axis = cam.get('axis_deg', 180.0)
        for b_deg, dist in cam['walls']:
            rel_b = (b_deg - axis + 180.0) % 360.0 - 180.0
            lat = dist * math.sin(math.radians(rel_b))
            long = dist * math.cos(math.radians(rel_b))
            if long > 0:
                if lat > 0 and lat < left_dist:
                    left_dist = lat
                elif lat < 0 and abs(lat) < right_dist:
                    right_dist = abs(lat)

    target_hitch = 0.0
    if left_dist < 50.0 and right_dist < 50.0:
        lateral_err = left_dist - right_dist
        target_hitch = -lateral_err * 8.0
        target_hitch = max(-25.0, min(25.0, target_hitch))
    elif left_dist < 50.0:
        if left_dist < 2.0:
            target_hitch = (2.0 - left_dist) * 10.0
    elif right_dist < 50.0:
        if right_dist < 2.0:
            target_hitch = -(2.0 - right_dist) * 10.0

    hitch_err = hitch - target_hitch
    steer = hitch_err * 2.2
    steer = max(-35.0, min(35.0, steer))

    if abs(hitch) > 20.0:
        speed = -0.7

    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look_target}

