    # Direct view walls:
    cab_left_hazard = False
    cab_left_critical = False
    if direct and 'walls' in direct:
        for b_deg, dist in direct['walls']:
            if b_deg > 0 and dist < 4.2:
                cab_left_hazard = True
            if b_deg > 5 and dist < 2.5:
                cab_left_critical = True

    # Camera rail detection
    left_dist = 999.0
    right_dist = 999.0
    if cam and 'walls' in cam:
        axis = cam.get('axis_deg', 180.0)
        for b_deg, dist in cam['walls']:
            rel_b = (b_deg - axis + 180.0) % 360.0 - 180.0
            lat = dist * math.sin(math.radians(rel_b))
            long = dist * math.cos(math.radians(rel_b))
            if long > 0:
                if lat > 0 and lat < left_dist:
                    left_dist = lat
                elif lat < 0 and abs(lat) < right_dist:
                    right_dist = abs(lat)

    target_hitch = 0.0
    if left_dist < 50.0 and right_dist < 50.0:
        lateral_err = left_dist - right_dist
        target_hitch = -lateral_err * 3.5
        target_hitch = max(-14.0, min(14.0, target_hitch))
    elif left_dist < 50.0 and left_dist < 2.5:
        target_hitch = (2.5 - left_dist) * 4.0
    elif right_dist < 50.0 and right_dist < 2.5:
        target_hitch = -(2.5 - right_dist) * 4.0

