    steer = hitch_err * 1.6
    steer = max(max_right_steer, min(20.0, steer))

    speed = -0.75
    if abs(hitch) > 12.0 or cab_left_hazard:
        speed = -0.45
    if cab_left_critical:
        speed = -0.3

    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look_target}

